const mic_glyph_t *mic_font_glyph(int size, uint16_t code)
{
    const mic_glyph_t *tbl; int n;
    switch (size) {
    case 16: tbl = s_tbl_16; n = 150; break;
    case 24: tbl = s_tbl_24; n = 150; break;
    case 40: tbl = s_tbl_40; n = 150; break;
    default: return 0;
    }
    int lo = 0, hi = n - 1;
    while (lo <= hi) {
        int mid = (lo + hi) / 2;
        if (tbl[mid].code == code) return &tbl[mid];
        if (tbl[mid].code < code) lo = mid + 1; else hi = mid - 1;
    }
    return 0;
}
const uint8_t *mic_font_bits(int size, const mic_glyph_t *g)
{
    if (size == 16) return s_bits_16 + g->off;
    if (size == 24) return s_bits_24 + g->off;
    if (size == 40) return s_bits_40 + g->off;
    return 0;
}

int mic_font_ascent(int size)
{
    if (size == 16) return 15;
    if (size == 24) return 22;
    if (size == 40) return 36;
    return 0;
}

